/* Месяцеслов «Православных» — 07.
   Каждый святой имеет краткое описание; lifeId — полное житие (src/lib/content/lives.ts). */

import type { SaintRec } from "./types";

export const M07: SaintRec[] = [
  { key: "07-01", name: "Прп. Леонтия, канонарха Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Леонтий Печерский (XIV в.) с юности подвизался в Киево-Печерской Лавре, где нес послушание канонарха, обладая прекрасным голосом. После блаженной кончины удостоился от Господа дара чудотворений." },
  { key: "07-01", name: "Василия Смирнова", kind: "saint", desc: "Сщмч. Василий Смирнов (1870-1938) родился в семье священника Московской губернии. Окончив духовную семинарию, преподавал Закон Божий, в 1914 г. рукоположен во священника." },
  { key: "07-01", name: "Александра Крутицкого", kind: "saint", desc: "Сщмч. Александр Крутицкий (1898-1938) родился в Московской губернии. Осиротев в 15 лет, воспитывался тётей. Окончив духовное училище, с 1917 г. служил псаломщиком, затем диаконом." },
  { key: "07-01", name: "Василия Крылова", kind: "saint", desc: "Сщмч. Василий Крылов (1899-1938) родился в семье псаломщика Московской губернии. Окончив Вифанскую духовную семинарию, служил в Красной армии. В 1922 г." },
  { key: "07-01", name: "Сергия Кроткова", kind: "saint", desc: "Сщмч. Сергий Кротков (1876-1938) родился в семье священника Рязанской губернии. Окончив духовную семинарию, в 1903 г. был рукоположен во священника. Во время Первой мировой войны служил полковым священником." },
  { key: "07-01", name: "прмч. Никанора (Морозкина), архимандрита", kind: "saint", desc: "Прмч. Никанор (Морозкин, 1870-1938) родился в крестьянской семье Рязанской губернии. В 1899 г. поступил в Николо-Перервинский монастырь, где принял монашество (1903) и был рукоположен в иеромонаха (1909)." },
  { key: "07-01", name: "свт. Виктора (Островидова), исп., епископа Глазовского", kind: "saint", desc: "Сщисп. Виктор (Островидов), епископ Глазовский, родился в 1875 г. в семье диакона Саратовской губернии. Окончил Казанскую духовную академию, принял монашество в 1903 г." },
  { key: "07-01", name: "Боголюбская", kind: "saint", desc: "Боголюбская икона Божией Матери, одна из древнейших чудотворных икон России, написана в XII веке по просьбе благоверного князя Андрея Боголюбского (память 4 июля) в память о явлении ему Божией Матери." },
  { key: "07-01", name: "Боголюбская", year: "Зимаровская", kind: "saint", desc: "Названа икона по наименованию села Зимарово Рязанской области. Представляет собой список (копию) владимирской Боголюбской иконы Божией Матери, одной из древнейших чудотворных икон России." },
  { key: "07-01", name: "Боголюбская", year: "Московская", kind: "saint", desc: "Икона Божией Матери Боголюбская-Московская была написана в 1157 году и находилась раньше в Москве на Соляной площади, над Варварскими воротами Китай-города." },
  { key: "07-01", name: "У Источника Пюхтицкая", kind: "saint", desc: "История чтимой иконы обители Успения Пресвятой Богородицы в Пюхтицах – образа Божией Матери «У источника» связана с именем великого всероссийского пастыря и молитвенника святого праведного Иоанна Кронштадтского ." },
  { key: "07-02", name: "Ап. Иуды Иаковлева, брата Господня", kind: "saint", desc: "Св. апостол Иуда, один из 12 учеников Христа, был сыном праведного Иосифа Обручника от первого брака. Первоначально не верил в Божественность Христа, но после искренне обратился." },
  { key: "07-02", name: "свт. Иова, патриарха Московского и всея Руси", kind: "saint", desc: "Свт. Иов (†1607), патриарх Московский и всея Руси, родился в г. Старице Тверской губернии. Приняв монашество, прошел путь от послушника до настоятеля Старицкого монастыря." },
  { key: "07-02", name: "свт. Иоанна (Максимовича), архиепископа Шанхайского и Сан-Францисского", kind: "saint", desc: "Свт. Иоанн Шанхайский и Сан-Францисский (1896-1966) ‒ выдающийся архипастырь Церкви. Родился в Харьковской губернии, с детства отличался глубокой верой." },
  { key: "07-02", name: "Прп. Варлаама Важского, Шенкурского", kind: "saint", desc: "Прп. Варлаам Важский (в миру Василий Своеземцев) – новгородский посадник, основатель Иоанно-Богословского монастыря на реке Ваге (Арханг. обл., 1444 г.)." },
  { key: "07-02", name: "мч. Зосимы Аполлониадского", kind: "saint", desc: "Мч. Зосима, воин из города Аполлони (Фракия), жил во времена гонений императора Траяна (II в.). Оставив военную службу, он принял Крещение и посвятил себя молитве." },
  { key: "07-02", name: "прп. Паисия Великого", kind: "saint", desc: "Прп. Паисий Великий (IV в.) ‒ египетский подвижник. С детства посвященный Богу, он принял монашество под руководством св. Памвы, проведя годы в строгом уединении и аскезе." },
  { key: "07-02", name: "прп. Иоанна Отшельника, Палестинского", kind: "saint", desc: "Прп. Иоанн Отшельник ‒ палестинский подвижник, живший в пещере близ Иерусалима в строгом посте и непрестанной молитве. Его единственным достоянием была икона Божией Матери, перед которой чудесным образом не угасала лампада." },
  { key: "07-02", name: "прп. Паисия Хилендарского (Афонского) (XVIII)", kind: "saint", desc: "Прп. Паисий Хилендарский родился в 1722 г. в Банско в благочестивой семье. Проходил послушание в Рыльском монастыре. В 1745 г. перешел на Афон, где принял постриг и глубоко изучил Священное Писание." },
  { key: "07-03", name: "Сщмч. Мефодия, епископа Патарского", kind: "saint", desc: "Сщмч. Мефодий Патарский (†312) — епископ Ликийский, известный своей кротостью и твердостью в вере. Будучи пламенным защитником православия, он активно противостоял ересям, особенно учению Оригена." },
  { key: "07-03", name: "блгв. кн. Глеба Владимирского (сына св. Андрея Боголюбского)", kind: "saint", desc: "Св. блгв. князь Глеб Владимирский (1155-1174), младший сын св. Андрея Боголюбского, с юных лет посвятил себя строгой подвижнической жизни, сочетая молитву, пост и милосердие." },
  { key: "07-03", name: "Свт. Мины, епископа Полоцкого", kind: "saint", desc: "Свт. Мина Полоцкий ‒ один из первых русских архиереев, начал свой духовный путь в Киево-Печерской Лавре. В 1105 г. был рукоположен во епископа Полоцкого, продолжив дело христианского просвещения Руси после её Крещения." },
  { key: "07-03", name: "перенесение мощей свт. Гурия, архиепископа Казанского", kind: "saint", desc: "Свт. Гурий (в миру Григорий Руготин, †1563), первый архиепископ Казанский, происходил из радонежских дворян. В юности, оклеветанный, два года провёл в заточении, после чего принял монашество в Иосифо-Волоколамском монастыре." },
  { key: "07-03", name: "свт. Левкия исп., епископа Врунтисиопольского", kind: "saint", desc: "Свт. Левкий Исповедник (V в.) – александрийский подвижник, воспитанный в монастыре св. Ермия. В 25 лет, несмотря на отказ по смирению, был поставлен игуменом, получив от Бога дар чудотворений." },
  { key: "07-03", name: "прав. Николая Кавасилы", kind: "saint", desc: "Св. праведный Николай Кавасила (ок. †1397) – выдающийся византийский богослов и церковный деятель. Получив блестящее образование в Константинополе, занимал должность сакеллария Константинопольской Церкви." },
  { key: "07-03", name: "Св. Николая Флорова исп., пресвитера", kind: "saint", desc: "Св. Николай Флоров ‒ исповедник веры, родился в 1870 г. в семье священника Вятской губернии. В 1932 г. был арестован за открытие общины и совершение богослужений." },
  { key: "07-03", name: "Моденская", year: "Косинская", kind: "saint", desc: "Икона Божией Матери Моденская-Косинская была привезена графом Борисом Петровичем Шереметьевым в 1717 году из итальянского города Модены. Икона именуется еще Косинской по месту своего пребывания в Успенской церкви бывшего подмосковного села Косино (сейчас район г." },
  { key: "07-04", name: "Мч. Иулиана Тарсийского", kind: "saint", desc: "Св. мч. Иулиан Тарсийский (ок. †305) ‒ юноша из знатной семьи, воспитанный матерью-христианкой. Во время гонений Диоклетиана 18-летний Иулиан отказался отречься от веры." },
  { key: "07-04", name: "Обретение мощей прп. Максима Грека", kind: "saint", desc: "Прп. Максим Грек (XV–XVI в.) ‒ выдающийся богослов и переводчик, уроженец Греции. Получив блестящее образование в Европе, принял монашество на Афоне. В 1518 г." },
  { key: "07-04", name: "Сщмч. Тертия (Терентия), епископа Иконийского", kind: "icon", desc: "Св. апостол Тертий (I в.) ‒ один из 70 учеников Христа, ближайший сотрудник апостола Павла. Лично записал Послание к Римлянам (Рим.16:22), так как апостол Павел имел неразборчивый почерк." },
  { key: "07-04", name: "Арчила II, царя Иверского (VIII),", kind: "saint", desc: "Св. мученик Арчил II (†744) ‒ благоверный царь Грузии из династии Хосроидов, правнук св. царя Мириана. В 736 г. вместе с братом Миром молитвами к Богородице одержал победу над арабским полководцем Мурваном-Кру." },
  { key: "07-04", name: "Луарсаба II, царя Карталинского (1622)", kind: "saint", desc: "Св. мученик Луарсаб II (1587-1622) ‒ благоверный царь Картли, взошедший на престол в юном возрасте. Отказавшись принять ислам по требованию персидского шаха Аббаса I, был заключён в крепость Гулаб-Кала, где 7 лет терпел мучения." },
  { key: "07-04", name: "Сщмч. Иоанна Будрина, пресвитера", kind: "saint", desc: "Сщмч. Иоанн Будрин (1866-1918) ‒ выпускник Пермской духовной семинарии, рукоположен в священники в 1889 г. Служил в Покровской церкви села Верхний Яр Пермской губернии, с 1902 г." },
  { key: "07-04", name: "прп. Георгия (Лаврова) исп., архимандрита Даниловского", kind: "saint", desc: "Прписп. Георгий (Лавров, †1932) ‒ оптинский старец, принявший монашество в 1899 г. После закрытия монастыря в 1918 г. арестован, чудом избежал расстрела.", lifeId: "georgiy" },
  { key: "07-04", name: "Алексия Скворцова", kind: "saint", desc: "Сщмч. Алексий Скворцов (1875-1938) ‒ выпускник Московской духовной семинарии, рукоположен в священники в 1917 г. Служил в Иоанно-Предтеченском храме московского Ивановского монастыря, после его закрытия ‒ в Успенской церкви поселка Гжель, затем в храме Архангела Михаила села Загорново." },
  { key: "07-04", name: "Павла Успенского", kind: "saint", desc: "Сщмч. Павел Успенский (1888-1938) ‒ выпускник Московской духовной семинарии, рукоположен во священники в 1913 г. Служил в храмах Московской области: в селах Сапроново, Васильевское, Чашниково, Болшево, Царицыно, Нехорошево, Рудня-Никитское." },
  { key: "07-04", name: "Николая Розанова", kind: "saint", desc: "Сщмч. Николай Розанов (1867-1938) ‒ священник, служивший 48 лет в храмах Московской губернии (Куликово, Черленково, Москва, Звенигород). В 1928 г. возведён в сан протоиерея и награждён митрой." },
  { key: "07-04", name: "прмч. Ионы (Санкова), иеромонаха", kind: "saint", desc: "Прмч. Иона (Санков) родился в 1873 г. в купеческой семье Рязанской губернии. В 1893 г. он поступил послушником в Свято-Пантелеимонов монастырь на Афоне, после пострижен в мантию и рукоположен в иеромонаха." },
  { key: "07-04", name: "мч. Никиты Сухарева", kind: "saint", desc: "Мч. Никита Сухарев (1876-1942) ‒ ткач из деревни Починки Рязанской губернии, активный член церковной общины Орехово-Зуево. В 1941 г. арестован за организацию ходатайств об открытии храма, обвинён в \"антисоветской агитации\" за сравнение гонений с римскими." },
  { key: "07-05", name: "Сщмч. Евсевия, епископа Самосатского", kind: "saint", desc: "Сщмч. Евсевий Самосатский (IV в.) ‒ ревностный защитник православия от арианской ереси. Несмотря на гонения императоров-ариан (Констанция, Валента), отказывался передать им церковные документы, за что был отправлен в ссылку." },
  { key: "07-05", name: "Мч. Албана Британского", kind: "saint", desc: "Св. мч. Албан Британский (†III в.) пострадал за веру во время гонений Диоклетиана (по др. данным ‒ Септимия Севера) в городе Веруламие (ныне северный пригород Лондона)." },
  { key: "07-05", name: "свт. Григория, митрополита Валашского (1834)", kind: "saint", desc: "Свт. Григорий IV Даскэл (1765–1834), митрополит Унгро-Влахийский, родился в Бухаресте, учился в академии св. Саввы. В 1790 г. постригся в монахи в Нямецком монастыре под руководством прп." },
  { key: "07-05", name: "Феодора Смирнова", kind: "saint", desc: "Сщмч. Феодор Смирнов (1890–1938) родился в семье псаломщика, окончил три курса Вифанской семинарии. В 1913 г. стал диаконом в селе Раменье, преподавал в земских школах." },
  { key: "07-05", name: "Гавриила Архангельского, диаконов", kind: "saint", desc: "Сщмч. Гавриил Архангельский (1885–1938) родился в семье псаломщика, служил в храмах Московской губернии, с 1915 г. – диакон в Петропавловской церкви при Мариинской больнице." },
  { key: "07-05", name: "Казанская Коробейниковская", kind: "saint", desc: "Коробейниковская Казанская икона Божией Матери, величайшая алтайская святыня, единственный в Сибири чудотворный образ, находилась в Богородице-Казанском храме села Коробейникова (Усть-Пристаньского района Алтайского края) с начала XX века." },
  { key: "07-06", name: "Владимирской иконы Божией Матери", kind: "icon", desc: "Владимирская икона Божией Матери написана Евангелистом Лукой на доске от стола, за которым трапезовал Спаситель с Пречистой Матерью и праведным Иосифом." },
  { key: "07-06", name: "Мц. Агриппины Римляныни", kind: "saint", desc: "Св. Агриппина (III в.), римлянка знатного рода, не пожелала вступать в брак, с юности посвятив себя Богу. Во время гонений при Валериане её обвинили в подрыве семейных устоев, но она мужественно защищала свою веру." },
  { key: "07-06", name: "Собор Владимирских святых", kind: "feast", desc: "Празднование собора святых, в земле Владимирской просиявших, было установлено в 1982 году по инициативе архиепископа Владимирского и Суздальского Серапиона (Фадеева) и по благословению патриарха Московского и всея Руси Пимена." },
  { key: "07-06", name: "Прав. отрока Артемия Веркольского", kind: "saint", desc: "Св. Артемий Веркольский (XVI в.) ‒ отрок-праведник, живший в селе Верколе. В 12 лет погиб от удара молнии, после чего односельчане, считая такую смерть знаком гнева Божия, оставили его тело непогребённым в лесу." },
  { key: "07-06", name: "Второе перенесение мощей свт. Германа, архиепископа Казанского и Свияжского", kind: "saint", desc: "Свт. Герман Казанский (XVI в.), происходивший из боярского рода Полевых, начал монашеский путь в Иосифо-Волоколамском монастыре под руководством св. Гурия." },
  { key: "07-06", name: "Александра Миропольского", kind: "saint", desc: "Сщмч. Александр Миропольский (1847-1918) ‒ протоиерей, миссионер среди крещеных татар. Окончив Казанскую духовную семинарию, служил в селе Апазово, где активно боролся с отпадением крещеных татар в ислам." },
  { key: "07-06", name: "Петра Смородинцева", kind: "saint", desc: "Сщмч. Петр Смородинцев (1866-1918), священник, был арестован красногвардейцами в 1918 г. и расстрелян вместе с протоиереем Александром Миропольским. Впоследствии, при приходе белых он был опознан лишь по подряснику: голова его была разбита в черепки топором или кайлом, а на теле обнаружены две огнестрельные раны." },
  { key: "07-06", name: "сщмч. Митрофана (Краснопольского), архиепископа Астраханского", kind: "saint", desc: "Сщмч. Митрофан (Краснопольский) (1869-1919) родился в Воронежской губернии. Окончил Киевскую духовную академию. С 1902 г. ‒ архимандрит, ректор Могилёвской духовной семинарии." },
  { key: "07-06", name: "Умиление Псково-Печерская", year: "1524", kind: "saint", desc: "По преданию, Псково-Печерская икона Божией Матери «Умиление» была написана в 1521 году неким иеромонахом Арсением (Хитрошем) с иконы Божией Матери «Владимирская»." },
  { key: "07-06", name: "Владимирская (Заоникиевская)", year: "1588", kind: "saint", desc: "Эта Владимирская икона явилась в 1588 году в 12 верстах от Вологды вологодскому поселянину Илариону – будущему преподобному Иосифу Заоникиевскому – при следующих обстоятельствах." },
  { key: "07-06", name: "Вратарница Угличская (Неугасимая Свеча)", year: "1894", kind: "saint", desc: "Богоматерь на сей иконе изображена в виде монахини с жезлом и четками в левой руке и свечой в правой руке. Образ этот находится в Алексеевском женском монастыре г." },
  { key: "07-07", name: "Рождество честного славного Пророка, Предтечи и Крестителя Господня Иоанна", kind: "feast", desc: "Когда Незаходимое Солнце правды – Спаситель наш восхотел воссиять миру и уже преклонил небеса и вселился в чистейшую девическую утробу, в это самое время должно было совершиться от неплодной рождение денницы Его – святого Иоанна Предтечи: е", lifeId: "ioann-predtecha" },
  { key: "07-07", name: "Прп. Антония Дымского", kind: "saint", desc: "Прп. Антоний Дымский (ок. 1157–1224) родился в Новгороде, с юных лет стремился к подвижничеству. Принял постриг в Хутынском монастыре у прп. Варлаама Хутынского, после его смерти стал игуменом обители." },
  { key: "07-08", name: "Прмц. Февронии девы", kind: "saint", desc: "Прмц. Феврония (ок. 304) – дева из монастыря в Сиваполе (Ассирия), воспитанная игуменией Вриенной. Во время гонений Диоклетиана военачальник Селин подверг её жестоким пыткам за отказ отречься от Христа: вырвал язык, отрезал грудь, руки и ноги, после чего обезглавил." },
  { key: "07-08", name: "прп. Далмата Исетского, Пермского, основателя Далматовского Свято-Успенского монастыря", kind: "saint", desc: "Основание Далматова монастыря в 1644 г. стало важной вехой в освоении Зауралья. Его создатель – бывший тобольский служилый человек Дмитрий Мокринский, принявший монашество с именем Далмат." },
  { key: "07-08", name: "Сщмч. Василия Милицына, пресвитера", kind: "saint", desc: "Сщмч. Василий Милицын (1861-1918) родился в Оренбургской губернии, окончил Камышловское уездное училище. В 1887 г. рукоположен в диаконы, с 1897 г. ‒ священник." },
  { key: "07-08", name: "прп. Никона Оптинского (Беляева), исп., иеромонаха", kind: "icon", desc: "Прп. Никон Оптинский, исп. (в миру Николай Беляев, 1888-1931) родился в московской купеческой семье. В 1907 г. пришел в Оптину пустынь, став ближайшим учеником старца Варсонофия." },
  { key: "07-08", name: "сщмч. Василия Протопопова, пресвитера", kind: "saint", desc: "Сщмч. Василий Протопопов (1886-1940) родился в семье псаломщика, окончил Смоленскую духовную семинарию. Рукоположен во священника в 1915 г., служил в Покровском храме села Новопокров в Смоленской губернии." },
  { key: "07-09", name: "Тихвинской иконы Божией Матери", year: "1383", kind: "icon", desc: "Тихвинская икона Божией Матери, по преданию, одна из икон, написанных святым апостолом и Евангелистом Лукой . В 1383 году, за 70 лет до взятия турками Константинополя, икона исчезла из храма и в лучезарном свете явилась над водами Ладожского озера." },
  { key: "07-09", name: "Прп. Давида Солунского (Фессалоникийского)", kind: "saint", desc: "Прп. Давид Солунский (V-VI вв.) ‒ греческий подвижник, 70 лет прожил в шалаше под миндальным деревом близ Фессалоник, пребывая в строгом посте и непрестанной молитве." },
  { key: "07-09", name: "Свт. Дионисия, архиепископа Суздальского", kind: "saint", desc: "Свт. Дионисий Суздальский (XIV в.), в миру Давид, начал монашеский путь в Киево-Печерской лавре, затем основал Вознесенский монастырь под Нижним Новгородом." },
  { key: "07-09", name: "прп. Тихона Луховского, Костромского", kind: "saint", desc: "Прп. Тихон Луховской (XV-XVI вв.) ‒ святой литовского происхождения. Будучи военным, оставил службу и переселился в Россию, избегая унии. Приняв монашество, основал пустынь в костромских землях, где подвизался в трудах и молитве." },
  { key: "07-09", name: "Перенесение мощей прп. Нила Столобенского", kind: "saint", desc: "Крестьянин из Новгородской земли, принял постриг в Крыпецком монастыре. После 10 лет в обители удалился в пустынь на реку Серемлю, затем по Божественному указанию поселился на острове Столобный на озере Селигер." },
  { key: "07-09", name: "прп. Иоанна, епископа Готфского", kind: "saint", desc: "Был рукоположен во епископа Готфии в Грузии (Иверии). Принимал участие в VII Вселенском Соборе (787 г.), восстановившем иконопочитание. Вернувшись в епархию, изгнал хазар из столицы Дори, но был захвачен ими и заключён в темницу." },
  { key: "07-09", name: "Сщмч. Георгия Степанюка, пресвитера", kind: "saint", desc: "Сщмч. Георгий Степанюк (1880-1918) родился в Гродненской губернии, работал учителем, затем принял священство. С 1911 г. служил в Туркестанской епархии.", lifeId: "georgiy" },
  { key: "07-09", name: "Лиддская (Римская)", kind: "saint", desc: "Проповедническая деятельность св. апостолов Петра и Иоанна Богослова, до их отшествия на проповедь Евангелия вне пределов Палестины, сосредоточивалась главным образом в городах, близких к Иерусалиму." },
  { key: "07-09", name: "Нямецкая", year: "1399", kind: "saint", desc: "Чудотворная Нямецкая икона Божией Матери в 1401 году была пожертвована Византийским императором Иоанном Палеологом Ясскому митрополиту Иосифу. Святая икона, переданная им в Вознесенский Нямецкий монастырь (основан в XIV веке), прославилась здесь многочисленными чудотворениями." },
  { key: "07-09", name: "Одигитрия Седмиезерная", year: "XVII", kind: "saint", desc: "Седмиезерная икона принадлежит к числу икон, пользующихся чрезвычайным почитанием в местах ее нахождения. День празднования в честь нее является торжеством не только для Седмиезерной пустыни и Казани, но и для всего Прикамского Поволжья." },
  { key: "07-10", name: "Прп. Сампсона Странноприимца", kind: "saint", desc: "Прп. Сампсон Странноприимец ‒ римский аристократ, ставший образцом христианского милосердия. Раздав наследство, он поселился в Константинополе, где безвозмездно лечил бедных и принимал странников." },
  { key: "07-10", name: "прав. Иоанны Мироносицы", kind: "saint", desc: "Св. Иоанна мироносица, жена Хузы ‒ домоправителя царя Ирода, была одной из благочестивых женщин, сопровождавших Христа во время Его земного служения. Она входила в число жен-мироносиц, которые пришли ко гробу Спасителя, чтобы помазать Его т" },
  { key: "07-10", name: "Обретение мощей прп. Амвросия Оптинского", kind: "saint", desc: "Прп. Амвросий Оптинский (1812-1891) ‒ великий русский старец, святость и богоугодность жития которого Бог засвидетельствовал многими чудесами. Родившись в семье пономаря, он после тяжелой болезни исполнил обет и поступил в Оптину пустынь (1839 г.).", lifeId: "amvrosiy-optinsky" },
  { key: "07-10", name: "Макария", kind: "saint", desc: "Прп. Макарий Оптинский (1788-1860), в миру Михаил Иванов, родился в семье орловских дворян. Оставив мирскую жизнь, в 1810 г. поселился в Площанской пустыни, где стал учеником старца Афанасия, последователя старца Паисия Величковского." },
  { key: "07-10", name: "Илариона", kind: "saint", desc: "Прп. Иларион (в миру Родион Пономарев, 1805-1873) родился в благочестивой семье воронежского портного. Тихий и кроткий, он с юности стремился к монашеству." },
  { key: "07-10", name: "Анатолия Старшего", kind: "saint", desc: "Прп. Анатолий Оптинский (Зерцалов) (1824-1894) родился в семье диакона Калужской губернии. После чудесного исцеления от чахотки, по обету, в 1853 г. поступил в Оптину пустынь, где стал духовным чадом преподобных старцев Макария и Амвросия." },
  { key: "07-10", name: "Варсонофия", kind: "saint", desc: "Прп. Варсонофий Оптинский (в миру Павел Плиханков, 1845-1913) ‒ великий оптинский старец, бывший военный, принявший монашество в 1900 г. Стал духовным преемником прп." },
  { key: "07-10", name: "Анатолия Младшего", kind: "saint", desc: "Прп. Анатолий Оптинский (Потапов) (1855-1922) ‒ один из последних оптинских старцев. С юных лет стремился к духовной жизни, но мать не отпускала его в монастырь, и только после ее смерти, в 1885 г., калужский приказчик Александр Потапов пришел в Оптину пустынь, став келейником прп." },
  { key: "07-10", name: "Прп. Серапиона Кожеезерского", kind: "saint", desc: "Прп. Серапион Кожеезерский (XVI-XVII вв.), в миру татарский мурза Туртас Гравирович, был пленён и крещён в Москве в 1551 г. Искренне восприняв христианскую веру, он решил всецело посвятить себя Богу." },
  { key: "07-10", name: "прп. Севира Валерийского (Италийского), пресвитера", kind: "saint", desc: "Прп. Севир, итальянский священник VI века, служил в храме Пресвятой Богородицы в селении Интероклея. Однажды, задержавшись в саду, он опоздал к умирающему, который скончался без покаяния." },
  { key: "07-10", name: "прп. Георгия Иверского, Святогорца (1065)", kind: "saint", desc: "Прп. Георгий Иверский (1009/1014-1066) ‒ грузинский святой, получивший образование в Константинополе. Приняв монашество, отправился на Афон, где продолжил переводческую деятельность прп.", lifeId: "georgiy" },
  { key: "07-10", name: "прп. Мартина Туровского", kind: "saint", desc: "Прп. Мартин Туровский ‒ повар, служивший при епископах в Борисоглебском монастыре. В старости, оставив службу, принял монашество и жил в уединении, страдая от болезней." },
  { key: "07-10", name: "Григория Никольского", kind: "saint", desc: "Сщмч. Григорий Никольский (1854-1918) ‒ потомственный донской казак, сын священника. После гражданской службы принял священный сан (1883 г.), служил в Астраханской и Ставропольской епархиях, занимался миссионерством и просвещением." },
  { key: "07-10", name: "сщмч. Петра Остроумова, пресвитера", kind: "saint", desc: "Сщмч. Петр Остроумов (1875-1939) родился в семье диакона Московской губернии. Окончив учительскую семинарию, в 1899 г. принял священный сан. Служил в Троицком храме родного села, где в 1929 г." },
  { key: "07-11", name: "Перенесение мощей мчч. бессребреников и чудотворцев Кира и Ио а нна", year: "412", kind: "feast", desc: "Святой бессребреник Кир был знаменитым врачом в городе Александрии, где родился и вырос. Он был христианином и лечил всех больных безвозмездно, не только подавая помощь в телесных болезнях, но исцеляя также и душевные недуги, которые бывают причинами телесных болезней." },
  { key: "07-11", name: "Прп. Ксенофонта Робейского, игумена", kind: "saint", desc: "Прп. Ксенофонт Робейский ‒ ученик св. Варлаама Хутынского, был игуменом Хутынского монастыря. Оставив игуменство, основал Троицкую обитель на реке Робейке под Новгородом." },
  { key: "07-11", name: "прп. Павла врача", kind: "saint", desc: "Прп. Павел Коринфянин ‒ монах-подвижник, живший в Коринфе. Однажды был оклеветан женщиной, обвинившей его в отцовстве её младенца. Смиренно приняв обвинение, святой попросил младенца указать на настоящего отца, и новорожденный чудесным образом назвал кузнеца." },
  { key: "07-11", name: "Сщмч. Василия Ситникова, диакона", kind: "saint", desc: "Сщмч. Василий Ситников ‒ диакон Далматовской Николаевской церкви (Пермская губ.). Окончил духовное училище, с 1885 г. служил псаломщиком, с 1898 г. ‒ диаконом в храмах Екатеринбургской епархии." },
  { key: "07-11", name: "прмц. Севастианы (Агеевой-Зуевой), монахини", kind: "saint", desc: "Прмц. Севастиана (Агеева-Зуева, 1872-1938) ‒ монахиня, духовная дочь сщмч. Серафима (Чичагова), помогавшая ему по хозяйству. Арестована в 1937 г. за \"антисоветскую агитацию\" (отказ признавать советскую власть и призывы бойкотировать выборы)." },
  { key: "07-11", name: "сщмч. Григория Самарина, диакона", kind: "saint", desc: "Сщмч. Григорий Самарин (1893-1940) родился в крестьянской семье в Пензенской губернии. Окончив духовное училище, служил псаломщиком, затем диаконом в храмах Средней Азии и Подмосковья." },
  { key: "07-11", name: "Троеручица", year: "VIII", kind: "saint", desc: "В VIII веке, во время иконоборчества, за ревностное почитание святых икон преподобный Иоанн Дамаскин (&dagger; ок. 780; память 4 декабря) был оклеветан императором Львом III Исавром (717–740) перед Дамасским калифом в государственной измене." },
  { key: "07-12", name: "Славных и всехвальных первоверховных апостолов Петра и Павла", kind: "feast", desc: "Почитание святых апостолов Петра и Павла началось сразу же после их казни. Место их погребения было священно для первых христиан. В IV веке святым равноапостольным Константином Великим (&dagger;337; память 21 мая ст.", lifeId: "petr-pavel" },
  { key: "07-12", name: "Свт. Григория, митрополита Ираклийского", kind: "saint", desc: "Свт. Григорий (Каллидос) (1844-1925) ‒ греческий иерарх, родившийся в Восточной Фракии. Служил на различных кафедрах: Трапезундской, Фессалоникийской, Янинской и Ираклийской." },
  { key: "07-12", name: "прп. Паисия Святогорца", kind: "saint", desc: "Прп. Паисий Святогорец (1924-1994) ‒ один из самых почитаемых греческих святых XX века. Родился в Каппадокии, грудным ребенком привезен в Грецию. В 1954 г.", lifeId: "pausiy-svyatogorets" },
  { key: "07-12", name: "Касперовская", kind: "saint", desc: "Касперовская чудотворная икона Божией Матери является великой святыней городов Херсона и Одессы, где она пребывает около шести месяцев в году. Дни принесения ее в Одессу (1 октября), и отшествия ее – в четвертый день Пасхи – стали великими церковными торжествами." },
  { key: "07-13", name: "Собор славных и всехвальных 12-ти апостолов", kind: "feast", desc: "Собор святых славных и всехвальных 12-ти Апостолов Христовых является древним праздником. Святая Церковь, чествуя каждого из 12-ти апостолов в разное время года, с давних времен установила общее празднование им на следующий день после памяти славных и первоверховных апостолов Петра и Павла (&dagger; ок." },
  { key: "07-13", name: "Андрея Первозванного", kind: "saint", desc: "Ап. Андрей Первозванный († 62), брат ап. Петра, был рыбаком из Галилеи. Первым последовал за Христом, приведя к Нему и св. Петра. После Пятидесятницы проповедовал в Малой Азии, Фракии, Македонии, прошел Крым, Причерноморье, дошел до поселений славян, где был основан Новгород.", lifeId: "andrey" },
  { key: "07-13", name: "Иакова Зеведеева", kind: "saint", desc: "Ап. Иаков Зеведеев (ок. 42/44 г.), брат ап. Иоанна Богослова, был рыбаком, призванным Христом. Входил в число ближайших учеников, присутствуя при важнейших событиях: воскрешении дочери Иаира, Преображении и в Гефсиманском саду." },
  { key: "07-13", name: "Иоанна Богослова", kind: "saint", desc: "Ап. Иоанн Богослов, любимый ученик Христа, был свидетелем ключевых событий Евангелия: Преображения, Тайной Вечери и Распятия. После Распятия он заботился о Богородице до Её Успения." },
  { key: "07-13", name: "Филиппа", kind: "saint", desc: "Ап. Филипп, уроженец Вифсаиды, упоминается в Евангелии как тот, кто привел к Иисусу ап. Нафанаила, участвовал в чуде насыщения 5000 и задавал вопросы на Тайной Вечере.", lifeId: "filipp" },
  { key: "07-13", name: "Варфоломея", kind: "saint", desc: "Св. апостол Варфоломей, один из 12 учеников Христа, проповедовал в Сирии, Малой Азии и Индии, где перевел Евангелие по Матфею. В Армении исцелил царскую дочь, обратил многих ко Христу, за что был казнен язычниками ‒ его распяли, с живого содрали кожу и обезглавили (71 г.)." },
  { key: "07-13", name: "Матфея", kind: "saint", desc: "Ап. Матфей, бывший мытарь, был призван Христом словами: \"Иди за Мной\". Оставив всё, он последовал за Спасителем и впоследствии написал Евангелие на еврейском языке.", lifeId: "matfey" },
  { key: "07-13", name: "Иакова Алфеева", kind: "saint", desc: "Ап. Иаков Алфеев, брат евангелиста Матфея, был призван Христом в число 12 учеников. После Пятидесятницы проповедовал в Иудее, затем вместе с ап. Андреем Первозванным ‒ в Едессе." },
  { key: "07-13", name: "Иуды Иаковлева", kind: "saint", desc: "Св. апостол Иуда, один из 12 учеников Христа, был сыном праведного Иосифа Обручника от первого брака. Первоначально не верил в Божественность Христа, но после искренне обратился." },
  { key: "07-13", name: "Симона Зилота", kind: "saint", desc: "Ап. Симон Зилот, уроженец Каны Галилейской, был призван Христом после чуда претворения воды в вино на свадьбе в его доме. Прозвище \"Зилот\" («ревнитель») указывает на его ревностную веру." },
  { key: "07-13", name: "Матфия", kind: "saint", desc: "Ап. Матфий, ученик Христа, был избран по жребию вместо Иуды Искариота в число 12 апостолов. Проповедовал в Иудее, Сирии и Малой Азии, совершая чудеса: остался невредим после отравленного питья, земля поглотила его гонителей." },
  { key: "07-13", name: "Прп. Петра, царевича Ордынского (Ростовского)", kind: "saint", desc: "Св. Петр царевич, племянник хана Золотой Орды Бергая, под влиянием бесед со свт. Кириллом, епископом Ростовским, тайно бежал в Ростов, где принял христианство." },
  { key: "07-13", name: "Прославление свт. Софрония, епископа Иркутского", kind: "saint", desc: "Свт. Софроний (в миру Стефан Кристалевский) родился в 1703 г. в Малороссии. Окончив Киевскую духовную академию, принял монашество в Красногорском монастыре, где ему было видение о будущем епископстве." },
  { key: "07-13", name: "Собор святых Биробиджанской епархии", kind: "feast", desc: "Празднование Собора святых Биробиджанской епархии внесено в месяцеслов по благословению Патриарха Московского и всея Руси Кирилла 7 июля 2018 года. День празднования Собора — 13 июля." },
  { key: "07-14", name: "Мч. Потита Гаргарского", kind: "saint", desc: "Св. мч. Потит, живший во II веке, принял Крещение, обратив в веру даже своего языческого отца. Проповедуя по разным странам, он совершал чудеса: исцелил от проказы знатную женщину Кириакию, после чего крестились её семья и слуги." },
  { key: "07-14", name: "прп. Петра патрикия", kind: "saint", desc: "Прп. Петр родился в Константинополе в VIII в. в знатной семье. Будучи военачальником, попал в плен к болгарам, но был чудесно освобожден по молитвам к ап." },
  { key: "07-14", name: "прп. Ангелины, деспотисы Сербской", kind: "saint", desc: "Прп. Ангелина Сербская (Бранкович), дочь албанского князя и супруга св. сербского короля Стефана, разделила с мужем изгнание, воспитав сыновей Максима и Иоанна в христианском благочестии." },
  { key: "07-14", name: "Сщмч. Аркадия Гаряева, пресвитера", kind: "saint", desc: "Сщмч. Аркадий Гаряев (1878–1918), венгр по происхождению, служил священником в селе Боровском Пермской губернии, преподавал в школе и занимался миссионерством среди вогулов." },
  { key: "07-14", name: "сщмч. Алексия Дроздова, протодиакона", kind: "saint", desc: "Сщмч. Алексий Дроздов (1883–1942) родился в Костромской губернии, окончил духовное училище и три курса семинарии. С 1904 г. служил диаконом в различных храмах России." },
  { key: "07-15", name: "Положение честной ризы Пресвятой Богородицы во Влахерне", kind: "feast", desc: "В годы правления византийского императора Льва Великого, Македонянина (457–474), братья Гальбий и Кандид, приближенные царя, отправились из Константинополя в Палестину на поклонение святым местам." },
  { key: "07-15", name: "Свт. Фотия, митрополита Киевского, Московского и всея Руси, чудотворца", kind: "saint", desc: "Грек из Монемвасии. В 1408 г. избран Константинополем на русскую кафедру. Перенёс митрополичью кафедру из Киева в Москву (1410), укрепив духовный центр Руси." },
  { key: "07-15", name: "свт. Иувеналия (Ювеналия), патриарха Иерусалимского", kind: "saint", desc: "Св. патриарх Иувеналий Иерусалимский был ревностным защитником православия. Участвовал в III (431 г.) и IV (451 г.) Вселенских Соборах, боровшихся с несторианством и монофизитством." },
  { key: "07-15", name: "Пожайская", year: "XVII", kind: "saint", desc: "На живописном берегу реки Неман у села Пожайце находился Пожайский Успенский мужской монастырь, основанный в XVII веке, драгоценной святыней которого была чудотворная икона Божией Матери, именуемая Пожайской." },
  { key: "07-15", name: "Феодотьевская", year: "1487", kind: "saint", desc: "Святыня Рязанской земли. Явилась в 1483 году в окрестностях Рязани в пустынном месте, именуемом «Старое», близ села Феодотьево. Поскольку от иконы стали совершаться многочисленные исцеления, то по повелению рязанского князя она была перенес" },
  { key: "07-15", name: "Ахтырская", year: "1739", kind: "saint", desc: "Ахтырская икона Божией Матери получила наименование от названия небольшого города Ахтырка в Харьковской губернии. В этом городке был храм в честь Покрова Пресвятой Богородицы, где в первой половине XVIII века жил благочестивый и добродетельный священник Василий Данилов (в службе он называется иереем Даниилом)." },
  { key: "07-16", name: "Мч. Иакинфа Римского", kind: "saint", desc: "Св. мученик Иакинф, происходивший из Кесарии Каппадокийской, служил постельничим при римском императоре Траяне. Во время языческого праздника, когда все участвовали в жертвоприношениях, он тайно молился Христу, за что был схвачен." },
  { key: "07-16", name: "Василия", kind: "saint", desc: "Св. блгв. князья Василий и Константин Ярославские, сыновья князя Всеволода Константиновича, погибшего в битве с монголами на реке Сить (†1238). Князь Василий (†1249) мудро правил Ярославским княжеством, восстанавливал храмы, ездил в Орду для защиты земель." },
  { key: "07-16", name: "Константина Ярославских", kind: "saint", desc: "Св. блгв. князья Василий и Константин Ярославские, сыновья князя Всеволода Константиновича, погибшего в битве с монголами на реке Сить (†1238). Князь Василий (†1249) мудро правил Ярославским княжеством, восстанавливал храмы, ездил в Орду для защиты земель." },
  { key: "07-16", name: "свт. Василия, епископа Рязанского", kind: "saint", desc: "По преданию, свт. Василий Рязанский начал свой духовный путь в Муроме, где принял монашество и был поставлен епископом. Когда по козням дьявола муромцы заподозрили его в грехе и изгнали, святитель чудесным образом переплыл на своей мантии по Оке до Рязани (200 км), держа в руках икону Богоматери." },
  { key: "07-16", name: "блж. Иоанна, Христа ради юродивого, Московского", kind: "saint", desc: "Блж. Иоанн Московский (XVI в.), прозванный \"Большим колпаком\" за железный головной убор, начал подвиг юродства в Ростове, нося вериги и терпя насмешки." },
  { key: "07-16", name: "прп. Никодима Кожеезерского", kind: "saint", desc: "Прп. Никодим Кожеезерский (в миру Никита) родился в крестьянской семье под Ростовом. Еще в молодости, работая в поле, он услышал слова: «Никодим! Никодим!», предвещавшие ему иночество." },
  { key: "07-16", name: "прп. Александра Константинопольского, обители «Неусыпающих» первоначальника", kind: "saint", desc: "Прп. Александр, основатель монастыря \"Неусыпающих\", начал свой путь как военный, но оставил мир ради монашества. После 4 лет послушания в сирийской обители и 7 лет пустынножительства с одним Евангелием, он обратил ко Христу градоначальника " },
  { key: "07-16", name: "свт. Анатолия, патриарха Константинопольского", kind: "saint", desc: "Свт. Анатолий, патриарх Константинопольский (V в.), получил философское образование в Александрии, где стал диаконом при свт. Кирилле. Участвовал в III Вселенском Соборе (431 г.), осудившем несторианство." },
  { key: "07-16", name: "Сщмч. Антония (Быстрова), архиепископа Архангельского", kind: "saint", desc: "Сщмч. Антоний (Быстров, 1858-1931) начал служение как приходской священник, после вдовства принял монашество. В 1921 г. стал епископом Архангельским, активно помогал заключённым и голодающим, за что в 1922 г." },
  { key: "07-16", name: "Обретение мощей свт. Сильвестра (Ольшевского), архиепископа Омского, исп.", kind: "saint", desc: "Сщисп. Сильвестр (Ольшевский, 1860-1920) родился в семье диакона, окончил Киевскую духовную академию, занимался миссионерской и педагогической деятельностью." },
  { key: "07-17", name: "Свт. Андрея, архиепископа Критского", kind: "saint", desc: "Свт. Андрей Критский (†740) родился в Дамаске, до 7 лет был немым, но исцелился после Св. Причастия. В 14 лет ушел в монастырь прп. Саввы Освященного, где прославился добродетелями." },
  { key: "07-17", name: "прп. Марфы Антиохийской, матери Симеона Дивногорца", kind: "saint", desc: "Прп. Марфа, мать св. Симеона Дивногорца, Столпника, с юности стремилась к монашеству, но по воле родителей вышла замуж. Овдовев, всецело посвятила себя воспитанию сына и делам милосердия: помогала нищим, ухаживала за больными, погребала умерших." },
  { key: "07-17", name: "прп. Андрея Рублева, иконописца", kind: "icon", desc: "Прп. Андрей Рублёв (ок. 1360–1428) – великий русский иконописец, монах. Принял постриг в московском Спасо-Андрониковом монастыре, около 20 лет подвизался вместе со св." },
  { key: "07-17", name: "Блгв. вел. кн. Андрея Боголюбского", kind: "saint", desc: "Св. блгв. князь Андрей Боголюбский (1110–1174), внук Владимира Мономаха, сын Юрия Долгорукого, с детства отличался благочестием. В 1155 г., не спросясь отца, перенес Владимирскую икону Богородицы из Вышгорода во Владимиро-Суздальские земли," },
  { key: "07-17", name: "Обретение мощей прп. Евфимия Суздальского, чудотворца", kind: "saint", desc: "Прп. Евфимий Суздальский (1316–1404) с детства отличался благочестием, усердно изучал Св. Писание. Приняв монашество в Нижегородском Печерском монастыре, исполнял тяжелые послушания, проводя ночи в молитвах." },
  { key: "07-17", name: "сщмч. Феодора, епископа Киринейского", kind: "saint", desc: "Сщмч. Феодор, епископ Киринейский, живший при императоре Диоклетиане (284–305), был искусным писцом, переписывавшим христианские книги. Его сын Лей донес правителю Дигниану, что отец распространяет христианство." },
  { key: "07-17", name: "сщмч. Саввы (Трлаича), епископа Горнокарловацкого (1941)", kind: "saint", desc: "Епископ Савва (Трлаич) родился в 1884 г. в Сербии, окончил семинарию и Белградский университет. После службы приходским священником в Башаиде и работы в Синоде, принял монашество в 1929 г." },
  { key: "07-17", name: "Сщмч. Димитрия Казанского, пресвитера", kind: "saint", desc: "Сщмч. Димитрий Казанский родился в семье диакона в Ярославской губернии. Служил священником в Севастьяновском женском монастыре до 1929 г., когда был арестован и осуждён на 5 лет лагерей за \"контрреволюционную деятельность\"." },
  { key: "07-17", name: "Галатская", kind: "saint", desc: "Наименование Галатской иконы Божией Матери происходит от названия одного из районов Константинополя – Галата. Предполагают, что первоначально святой образ пребывал в монастыре, сооруженном в честь святой иконы, который просуществовал до ХVII века." },
  { key: "07-18", name: "Прп. Афанасия, игумена Афонского", kind: "saint", desc: "Прп. Афанасий Афонский (†1000) родился в Трапезунде, получил образование в Византии. Приняв постриг в Киминском монастыре, с усердием исполнял монастырские послушания, переписывал священные книги." },
  { key: "07-18", name: "Обретение честных мощей прп. Сергия, игумена Радонежского, чудотворца", kind: "saint", desc: "Прп. Сергий (в миру Варфоломей, 1314-1392), великий русский святой, был сыном ростовских бояр. С детства он стремился к учению, но грамота давалась с трудом, пока чудесная встреча с монахом не даровала ему разумение.", lifeId: "sergiy" },
  { key: "07-18", name: "Агнии (Анны) девы", kind: "saint", desc: "Мц. Агния (Анна), 13-летняя христианка из Рима. Когда она отказалась поклоняться языческим богам и выходить замуж за сына римского чиновника, её пытались опозорить, отправив в дом терпимости." },
  { key: "07-18", name: "Кириллы Киринейской", kind: "saint", desc: "Святая мученица Кирилла (Киприлла) Киринейская пострадала за веру Христову в 304 году, была усечена мечом после жестоких пыток за отказ поклониться идолам." },
  { key: "07-18", name: "прп. Лампада Иринопольского", kind: "saint", desc: "Подвизался в X веке в посте и молитвах в пещере близ Иринополя, в Исаврии, и прославлен даром чудес. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку '" },
  { key: "07-18", name: "Сщмч. Геннадия Здоровцева, пресвитера", kind: "saint", desc: "Сщмч. Геннадий Здоровцев родился в 1868 г. в семье священника. Окончил Ярославскую семинарию, служил в храмах Любимского уезда, с 1907 г. ‒ в Ярославском Кафедральном соборе, а с 1914-го стал настоятелем Владимирской церкви Ярославля." },
  { key: "07-18", name: "прмцц. вел. кн. Елисаветы", kind: "saint", desc: "Великая княгиня Елисавета Феодоровна, немецкая принцесса по рождению, приняла православие в 1891 г. После трагической гибели мужа от рук террориста полностью посвятила себя служению Богу и ближним, основав в Москве Марфо-Мариинскую обитель ‒ уникальный центр духовной и медицинской помощи." },
  { key: "07-18", name: "инокини Варвары (Яковлевой)", kind: "saint", desc: "Инокиня Варвара (Яковлева) была одной из первых сестёр Марфо-Мариинской обители милосердия и келейницей великой княгини Елисаветы Феодоровны. Отличалась кротостью, трудолюбием и глубокой верой." },
  { key: "07-18", name: "прп. Агапита (Таубе) исп., монаха", kind: "saint", desc: "Прписп. Агапит (в миру Михаил Таубе) родился в 1894 г. в Гатчине. Окончив три курса юридического факультета, служил в армии, был ранен. После революции работал в музее Оптиной Пустыни, где стал духовным сыном иеромонаха Никона (Беляева), который и постриг его в мантию." },
  { key: "07-18", name: "Экономисса", year: "Домостроительница", kind: "saint", desc: "Икона Пресвятой Богородицы, именуемая «Экономисса» или «Домостроительница» находится на Афонской горе , в лавре св. Афанасия . История ее появления такова." },
  { key: "07-19", name: "Прп. Сисоя Великого", kind: "saint", desc: "Прп. Сисой Великий († 429) ‒ египетский подвижник, 60 лет подвизавшийся в пещере прп. Антония Великого. Обладая даром чудотворения (воскресил отрока), он особенно прославился глубочайшим смирением." },
  { key: "07-19", name: "Собор Радонежских святых", kind: "feast", desc: "История установления Собора Радонежских святых восходит к середине XVII века. Именно в то время были восстановлены первые списки учеников преподобного Сергия Радонежского, был напечатан «Канон молебен преподобным и богоносным отцам нашим игумену Сергию и ученику его Никону, чудотворцам»." },
  { key: "07-19", name: "Прп. Сисоя, схимника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Сисой Печерский ‒ схимонах XIII века, подвизавшийся в Киево-Печерской лавре. Прославился строгим постничеством и подвижнической жизнью. Его мощи почивают в Дальних (Феодосиевых) пещерах." },
  { key: "07-19", name: "Обретение мощей прав. девы Иулиании, кн. Ольшанской", kind: "saint", desc: "Княжна Иулиания Ольшанская (XVI в.), умершая в 16 лет, была погребена у стен Киево-Печерской Лавры. Через полвека её гроб обрели с нетленным телом в богатом убранстве." },
  { key: "07-19", name: "мч. Коинта Фригийского", kind: "saint", desc: "Св. мч. Коинт Фригийский с юности был наставлен в христианской вере и благочестии. Когда правитель Руф, заставлявший его принести жертву идолам, сам впал в беснование, святой исцелил его именем Христовым." },
  { key: "07-19", name: "Тихона", kind: "saint", desc: "Прп. Тихон, Василий и Никон Соколовские ‒ братья, подвизавшиеся в XVI веке в Подмосковье. Изображены на древней иконе в схимнических одеждах. Погребены в Соколовой роще." },
  { key: "07-19", name: "Василия", kind: "saint", desc: "Прп. Тихон, Василий и Никон Соколовские ‒ братья, подвизавшиеся в XVI веке в Подмосковье. Изображены на древней иконе в схимнических одеждах. Погребены в Соколовой роще." },
  { key: "07-19", name: "Никона Соколовских (XVI)", kind: "icon", desc: "Прп. Тихон, Василий и Никон Соколовские ‒ братья, подвизавшиеся в XVI веке в Подмосковье. Изображены на древней иконе в схимнических одеждах. Погребены в Соколовой роще." },
  { key: "07-19", name: "свт. Арсения, епископа Тверского", kind: "saint", desc: "Свт. Арсений, епископ Тверской, принял постриг в Киево-Печерской лавре, где выделялся строгой подвижнической жизнью. В 1390 г., несмотря на первоначальный отказ, был назначен на Тверскую кафедру, где прекратил княжеские междоусобицы." },
  { key: "07-19", name: "Собор Тверских святых", kind: "feast", desc: "С 1897 года по благословению архиепископа Тверского и Кашинского Димитрия (Самбикина; &dagger; 17 марта 1908 г.) началось собирание сведений о Тверских святых." },
  { key: "07-19", name: "Прмч. Евфимия (Любовичева), иеромонаха", kind: "saint", desc: "Прмч. Евфимий (Любовичев) родился в 1875 г. в Калужской губернии. В 1902 г. поступил в Оптину пустынь, где стал келейником старца Анатолия (Потапова). После революции работал в музее на территории закрытого монастыря." },
  { key: "07-19", name: "прмч. Феодора (Богоявленского), иеромонаха", kind: "saint", desc: "Прмч. Феодор (в миру Олег Богоявленский) родился в 1905 г. в Тегеране в благочестивой семье русского консула в Персии. После гибели отца в 1911 г. семья переехала в Петербург, а затем в Саратов и Москву, переживая революционные потрясения и голод." },
  { key: "07-19", name: "Валаамская", kind: "saint", desc: "Икона, написанная в 1878 году валаамским иконописцем Алипием, по неизвестным причинам около двадцати лет пролежала в монастырской кладовой церкви святителя Николая." },
  { key: "07-19", name: "Казанская (Богородско-Уфимская)", year: "1621", kind: "saint", desc: "Время обретения чудотворной Богородско-Уфимской иконы Божией Матери (копия Казанской, только более темных тонов) относится к началу XVII века – времени, когда на территории современной Башкирии образовывались первые православные поселения." },
  { key: "07-20", name: "Прп. Фомы, иже в Малеи", kind: "saint", desc: "Прп. Фома Малеин, византийский святой X века, начал жизнь как храбрый воин, но, оставив мир, принял монашество. Стремясь к уединению, он последовал за чудесным огненным столпом, приведшим его на гору Малея, где получил благословение от явившегося пророка Илии." },
  { key: "07-20", name: "прп. Акакия Синайского, о котором повествуется в Лествице", kind: "saint", desc: "Прп. Акакий, ученик сурового старца, девять лет терпел жестокие обиды и побои, но всегда отвечал: \"Как перед Господом – мне хорошо\". Даже после смерти, когда старец усомнился в его кончине, Акакий откликнулся из гроба: \"Творящий послушание не может умереть\"." },
  { key: "07-20", name: "Прп. Евфросинии, в миру Евдокии, вел. кн. Московской", kind: "saint", desc: "Супруга блгв. кн. Дмитрия Донского. С юных лет отличалась глубоким благочестием. Во время Куликовской битвы молилась за победу русского войска, а после победы построила в Кремле храм Рождества Пресвятой Богородицы." },
  { key: "07-20", name: "прп. Герасима Болдинского", kind: "saint", desc: "Прп. Герасим Болдинский (1490-1554) – русский подвижник XVI века. Начав монашеский путь под руководством прп. Даниила Переяславского, он 26 лет подвизался в Горицком монастыре, после чего ушел в смоленские леса." },
  { key: "07-20", name: "сщмч. Евангела, епископа Томского", kind: "saint", desc: "Сщмч. Евангел упоминается в житии мучеников Епиктета и Астиона как епископ города Томы (совр. Констанца, Румыния). Он крестил родителей св. Астиона после мученической кончины последнего." },
  { key: "07-20", name: "мц. Кириакии Никомидийской", kind: "saint", desc: "Св. мц. Кириакия, единственная дочь благочестивых христиан, пострадала в Никомидии при императоре Диоклетиане (IV в.). Отправленная на суд, она мужественно перенесла пытки, по её молитвам рухнули языческие идолы, а выпущенные звери покорно ложились у ног." },
  { key: "07-20", name: "Сщмч. Павла Чернышева, пресвитера", kind: "saint", desc: "В июле 1918 г. священник Павел Чернышев, 28 лет служивший в Пермской губернии, был вместе с сыном и прихожанами насильно вывезен из села под предлогом мобилизации на окопные работы." },
  { key: "07-20", name: "Влахернская", kind: "saint", desc: "Влахернская икона Божией Матери обретена в Иерусалиме императрицей Евдокией во времена святителя Ювеналия, Патриарха Иерусалимского (память 2 июля), и преподобного Евфимия Великого (память 20 января)." },
  { key: "07-21", name: "Явление иконы Пресвятой Богородицы во граде Казани", year: "1579", kind: "icon", desc: "1 октября 1552 года, в праздник Покрова Пресвятой Богородицы, ночью, Иоанн IV, предводитель русских воинов, готовившихся к решительному штурму татарской Казани, вдруг услышал благовест московских колоколов." },
  { key: "07-21", name: "вмч. Прокопия Кесарийского", kind: "saint", desc: "Св. вмч. Прокопий (в миру Неаний), знатный римлянин, был назначен проконсулом для гонений на христиан. По пути в Александрию ему явился Христос, после чего он сам обратился в христианство." },
  { key: "07-21", name: "прав. Прокопия Устюжского, Христа ради юродивого, чудотворца", kind: "saint", desc: "В XIII веке немецкий купец Прокопий, прибыв в Новгород, был поражён красотой православия, принял веру и раздал имущество. Став юродивым, он скитался, терпя лишения, пока не поселился в Устюге, где предрёк городу бедствие от каменно-огненной тучи, но молитвами Прокопия Устюг был спасён." },
  { key: "07-21", name: "Прав. Прокопия Устьянского", kind: "saint", desc: "В XVII веке близ Устьянской Введенской церкви Вологодской епархии были обретены нетленные мощи праведного Прокопия, источавшие чудеса. Его имя открылось в видении местному жителю Савелию." },
  { key: "07-21", name: "Феодора Распопова", kind: "saint", desc: "Сщмч. Феодор Распопов (1891–1918) родился в крестьянской семье в Тобольской губернии. Окончил Тобольскую духовную семинарию, учился в Казанской академии, но оставил её ради служения в епархии." },
  { key: "07-21", name: "Николая Брянцева", kind: "saint", desc: "Сщмч. Николай Брянцев (1867–1918) служил в Пятницко-Туговской церкви Ярославля. 8 июля 1918 года был расстрелян большевиками за отказ разрешить установку пушки на колокольне для обстрела города." },
  { key: "07-21", name: "Благовещение Устюжская", year: "1290", kind: "great", desc: "Почитание чудотворной Устюжской иконы Божией Матери тесно связано с именем преподобного Прокопия , Христа ради юродивого, подвизавшегося в Великом Устюге." },
  { key: "07-21", name: "Казанская (Московская)", year: "1612", kind: "saint", desc: "Список с чудотворной Казанской иконы Божией Матери, находившийся в русском ополчении, перед которым в 1612 году молились патриоты Минин и Пожарский, был поставлен в 1636 году в Московском Казанском соборе ." },
  { key: "07-21", name: "Казанская (Казанский список)", year: "1579", kind: "saint", desc: "Чудотворный список с Казанской иконы Божией Матери, обретенной в 1579 году, находится в Казанском кладбищенском храме во имя святых благоверных князей Феодора и чад его Давида и Константина." },
  { key: "07-21", name: "Казанская (Петербургский список)", year: "1721", kind: "saint", desc: "Главной святыней Казанского кафедрального собора Санкт-Петербурга является Казанская икона Божией Матери, во имя которой собор был построен в 1811 г. Эта икона, чудесным образом явленная в г." },
  { key: "07-21", name: "Казанская (Ярославская)", year: "1588", kind: "saint", desc: "Об обстоятельствах прославления Казанской (Ярославской) иконы Божией Матери известно следующее. В 1588 году одному благочестивому христианину по имени Герасим, страстно желавшему иметь у себя икону Успения Пресвятой Богородицы, во сне явила" },
  { key: "07-21", name: "Казанская (Вязниковская)", year: "1624", kind: "saint", desc: "Казанская икона Божией Матери, именуемая Вязниковской, находилась в соборном храме города Вязники Владимирской епархии. Святая икона прославилась многочисленными чудесами." },
  { key: "07-21", name: "Казанская (Нижнеломовская)", year: "1643", kind: "saint", desc: "Казанская чудотворная икона Божией Матери, именуемая Нижнеломовской, явилась в 1643 году близ города Нижнего Ломова Пензенской губернии. 8 (21) июля некий казак Андрей Михайлов сын Набоков увидел Казанскую икону Божией Матери, стоявшую на пне возле источника, и доложил об этом воеводе." },
  { key: "07-21", name: "Казанская (Витебская)", year: "1655", kind: "saint", desc: "Святыня древнего Маркова Свято-Троицкого монастыря Витебской епархии, возведённого в XVII веке в селе Марково. Во время русско-польской войны 1654–1667 годов Витебск и Полоцк на некоторое время перешли к Московскому государству, в связи с чем монастырь стал подчиняться Московскому Патриархату." },
  { key: "07-22", name: "Сщмч. Панкратия, епископа Тавроменийского", kind: "saint", desc: "Сщмч. Панкратий Тавроменийский родился в Антиохии и жил во времена земной жизни Христа. Услышав о благовестии, он уверовал во Христа, познакомился с апостолом Петром и после смерти родителей удалился в горы для молитвы." },
  { key: "07-22", name: "Прп. Гавриила Афонского, настоятеля афонского Ильинского скита", kind: "saint", desc: "Прп. Гавриил (в миру Георгий) родился в 1849 году в бедной семье Киевской губернии. Рано осиротев, он отправился паломником по святым местам, что определило его монашеский путь." },
  { key: "07-22", name: "сщмч. Кирилла, епископа Гортинского", kind: "saint", desc: "Сщмч. Кирилл, епископ, 50 лет возглавлявший кафедру в Гортине (Крит), пострадал во время гонений при императоре Декии (249-251 гг.) или Диоклетиане (284-305 гг.)." },
  { key: "07-22", name: "Патермуфия", kind: "saint", desc: "Прп. Патермуфий, бывший разбойник, после крещения удалился в пустыню, посвятив жизнь служению больным и погребению умерших, за что удостоился дара чудотворения." },
  { key: "07-22", name: "Коприя", kind: "saint", desc: "Прп. Патермуфий, бывший разбойник, после крещения удалился в пустыню, посвятив жизнь служению больным и погребению умерших, за что удостоился дара чудотворения." },
  { key: "07-22", name: "свт. Феодора, епископа Едесского", kind: "saint", desc: "Свт. Феодор Едесский (IX в.), оставив мир в 20 лет, принял постриг в Лавре прп. Саввы, где 12 лет подвизался в послушании, а затем 24 года ‒ в затворе." },
  { key: "07-22", name: "Сщмч. Константина Лебедева, пресвитера", kind: "saint", desc: "Сщмч. Константин Лебедев (1884-1918) родился в Пермской губернии, окончил духовную семинарию и в 1912 году был рукоположен в священника. Служил в Спасской церкви села Уецкого Камышловского уезда." },
  { key: "07-22", name: "Колочская", year: "1413", kind: "saint", desc: "Как свидетельствуют старинные летописи и древнерусская «Повесть о Луке Колочском», чудотворная Колочская икона Божией Матери явилась в 1413 году в вотчине князя Андрея Димитриевича, внука Иванова, правнука Иванова и праправнука Даниила Моск" },
  { key: "07-22", name: "Кипрская", year: "Стромынская", kind: "saint", desc: "Одним из списков древней чудотворной Кипрской иконы Божией Матери является святыня не сохранившегося до наших дней Стромынского монастыря (бывшего Богородского уезда, Московской епархии), находящаяся ныне в Успенской церкви села Стромынь." },
  { key: "07-23", name: "Положение честн о й ризы Господа нашего Иисуса Христа в Москве", year: "1625", kind: "feast", desc: "Честную Ризу Спасителя не следует отождествлять с нешвенным Его Хитоном – они ясно различаются в Священном Писании: «Воины же, когда распяли Иисуса, взяли одежды Его и разделили на четыре части, каждому воину по части, и хитон; хитон же был не сшитый, а весь тканый сверху." },
  { key: "07-23", name: "прп. Антония Печерского, Киевского, начальника всех русских монахов", kind: "saint", desc: "Основатель Киево-Печерской Лавры прп. Антоний, уроженец Любеча (вблизи Чернигова), принял постриг на Афоне, а затем по послушанию игумену вернулся на Русь, поселившись в 1051 году в пещере близ Киева.", lifeId: "pecherskie" },
  { key: "07-23", name: "Прп. Силуана, схимника Печерского, в Дальних пещерах", kind: "saint", desc: "Прп. Силуан, Киево-Печерский схимник (XIII-XIV вв.), прославился строгой аскезой, непрестанной молитвой и духовными дарами – прозорливостью, чудотворениями и особой благодатной радостью." },
  { key: "07-23", name: "мч. Аполлония Иконийского", kind: "icon", desc: "Св. мч. Аполлоний, уроженец Сард (Лидия), открыто исповедал христианство и был схвачен. Отказавшись клясться именем императора, он подвергся жестоким мучениям и был распят в Иконии во время гонений при императоре Декии (249-251) или Валериане (253-259)." },
  { key: "07-23", name: "преподобных пустынников египетских, огнем и дымом уморенных", year: "ок. 398", kind: "saint", desc: "Десять тысяч обитателей пустынь были обвинены в оригенизме и замучены около 398 года при Александрийском патриархе Феофиле. Реальной причиной их убийства считают то, что они предоставили убежище священнику Исидору." },
  { key: "07-23", name: "Александра Попова", kind: "saint", desc: "Сщмч. Александр Попов (1869-1918) родился в семье церковнослужителя Пермской губернии. Окончив Пермскую духовную семинарию, с 1890 года служил священником в селе Травянское Камышловского уезда, преподавал Закон Божий." },
  { key: "07-23", name: "Василия Победоносцева", kind: "saint", desc: "Сщмч. Василий Победоносцев (1848-1918) родился в Пермской губернии, окончил духовную семинарию и в 1878 году был рукоположен во священника. Служил в Свято-Троицком соборе Каменского завода." },
  { key: "07-23", name: "Петра Зефирова", kind: "saint", desc: "Сщмч. Петр Зефиров (1879-1918) родился в Ярославской губернии, окончил духовную семинарию и после трёх лет преподавания был рукоположен во иерея. Служил в селе Николо-на-Эдоме, воспитывал шестерых детей." },
  { key: "07-23", name: "Коневская", kind: "saint", desc: "Этой святой иконой греческого письма благословил в 1393 году святого Арсения, основателя Коневской обители (сведения о нем помещены 12 июня), преподобный Иоанн, игумен одной из афонских обителей." },
  { key: "07-24", name: "Воспоминание чуда вмц. Евф и мии Всехвальной, имже Православие утвердися", year: "451", kind: "feast", desc: "Святая великомученица Евфимия совершила мученический подвиг в городе Халкидоне в 304 году, во время гонения, воздвигнутого на христиан императором Диоклетианом (284–305)." },
  { key: "07-24", name: "равноап. Ольги, вел. княгини Российской, во Святом Крещении Елены", kind: "saint", desc: "Св. равноапостольная Ольга (ок. 890-969), княгиня Киевская, стала первым правителем Руси, принявшим христианство. После гибели мужа, князя Игоря, посвятила жизнь укреплению государства.", lifeId: "olga-vladimir" },
  { key: "07-24", name: "обретение мощей сщмч. Илариона (Троицкого), архиепископа Верейского", kind: "saint", desc: "Архиепископ Верейский Иларион (Троицкий, 1886-1929) ‒ выдающийся богослов и церковный деятель, ближайший сподвижник Патриарха Тихона. Окончив Московскую духовную академию, принял монашество (1913) и активно участвовал в восстановлении патриаршества на Поместном Соборе 1917-1918 гг." },
  { key: "07-24", name: "Сщмч. Киндея Сидского (Памфилийского), пресвитера", kind: "saint", desc: "Сщмч. Киндей, пресвитер из селения Сиды в Памфилии, пострадал во время гонений императора Диоклетиана (284-305 гг.). Приведённый на казнь, он сам заплатил дровосеку за дрова для своего костра и понёс их к месту казни." },
  { key: "07-24", name: "Оковецкая (Ржевская)", year: "1539", kind: "saint", desc: "26 мая 1539 года, в день Сошествия Святого Духа, в Тверской епархии, на Вырышенском городище, находившемся среди дремучего леса на берегу речки Вырышни в Оковецкой волости, недалеко от города Ржева, иноком Стефаном при стечении народа из че" },
  { key: "07-24", name: "Борколабовская", year: "Барколабовская", kind: "saint", desc: "Борколабовская (Барколабовская) икона Божией Матери – чудотворный образ, получивший свое название по месту своего нахождения в главной церкви Борколабовского женского монастыря в честь Вознесения Господня в селе Борколабове Быховского района Могилевской области (Республика Беларусь)." },
  { key: "07-25", name: "прп. Михаила Малеина, игумена", kind: "saint", desc: "Прп. Михаил Малеин родился около 894 года в Каппадокии, происходил из знатного рода, был связан с императором Львом VI. Получив образование, служил при дворе, но в 18 лет ушел в монастырь, приняв постриг." },
  { key: "07-25", name: "Феодора Варяга", kind: "saint", desc: "Св. мученик Феодор, бывший воин, принявший крещение в Византии, и его сын Иоанн пострадали в Киеве в 983 году. Когда великий князь Владимир, тогда еще ревностный язычник, после победы над ятвягами решил принести человеческую жертву, жребий пал на Иоанна." },
  { key: "07-25", name: "сына его Иоанна Печерского, в Киеве", kind: "saint", desc: "Св. мученик Феодор, бывший воин, принявший крещение в Византии, и его сын Иоанн пострадали в Киеве в 983 году. Когда великий князь Владимир, тогда еще ревностный язычник, после победы над ятвягами решил принести человеческую жертву, жребий пал на Иоанна." },
  { key: "07-25", name: "прп. Арсения Новгородского", kind: "saint", desc: "Прп. Арсений Новгородский (в миру Амвросий) родился в Ржеве в благочестивой семье. Оставив жену и дом, тайно ушел в Новгород, где пять лет трудился кожевником, соблюдая строгий пост." },
  { key: "07-25", name: "прмч. Симона Воломского, игумена", kind: "saint", desc: "Прмч. Симон Воломский (в миру Симеон) родился в 1586 году в крестьянской семье. В юности ушел в монастырь на реке Пинеге, где принял постриг. Стремясь к уединению, в 1613 году поселился в глухом лесу на реке Кичменге, где основал обитель с храмом Воздвижения Креста Господня." },
  { key: "07-25", name: "прав. Вероники Кровоточивой, Палестинской", kind: "saint", desc: "Праведная Вероника, по преданию, та самая кровоточивая женщина, исцелившаяся от прикосновения к одежде Христа (Мф.9:20-22). Во время крестного пути Спасителя она подала Ему воды и утерла Его окровавленное лицо своим платом, на котором чудесно запечатлелся Его лик." },
  { key: "07-25", name: "св. Голиндухи, во Святом Крещении Марии, исп.", kind: "saint", desc: "Св. Голиндуха (в Крещении Мария), бывшая жена персидского волхва, приняла христианство после явления ей Ангела, показавшего ад и рай. За отказ вернуться к мужу-язычнику 18 лет провела в тюрьме при царе Хозрое I." },
  { key: "07-25", name: "Иоанна", kind: "saint", desc: "Прп. Иоанн, отец св. Евфимия Нового, происходил из знатного грузинского рода. Оставив мирскую жизнь, принял схиму в Имеретинском монастыре, затем подвизался на горе Олимп." },
  { key: "07-25", name: "Гавриила (X) Святогорцев", kind: "saint", desc: "Прп. Гавриил Святогорец, грузинский подвижник, подвизался в Иверской обители на Св. Горе Афон. Удостоился явления Божией Матери, повелевшей ему принять из моря Её икону." },
  { key: "07-25", name: "Троеручица", year: "VIII", kind: "saint", desc: "В VIII веке, во время иконоборчества, за ревностное почитание святых икон преподобный Иоанн Дамаскин (&dagger; ок. 780; память 4 декабря) был оклеветан императором Львом III Исавром (717–740) перед Дамасским калифом в государственной измене." },
  { key: "07-26", name: "Собор Архангела Гавриила", kind: "feast", desc: "Благовестника нашего спасения, великого слугу Божьего и радостного посланника к Пречистой Деве Марии ( Лк.1:26 ), Архангела Гавриила мы восхваляем в песнопениях, составляя ему второй раз праздничный собор." },
  { key: "07-26", name: "Прп. Стефана Савваита", kind: "saint", desc: "Прп. Стефан Савваит, племянник св. Иоанна Дамаскина, родился в 725 году. С 10 лет подвизался в Лавре св. Саввы, периодически уходя в пустыню для уединения." },
  { key: "07-26", name: "Свт. Иулиана, епископа Кеноманийского", kind: "saint", desc: "Свт. Иулиан Кеноманийский, рукоположенный апостолом Петром, проповедовал в Северной Италии (I в.). Поселившись в хижине под Кремоной, он обращал язычников, совершая чудеса: исцелял болезни, воскрешал умерших, жезлом извёл источник воды." },
  { key: "07-26", name: "мч. Серапиона", kind: "saint", desc: "Св. мученик Серапион пострадал за веру во Христа при императоре Севере. Представ перед правителем Акилой, он смело исповедал христианство, за что был жестоко истязаем и брошен в темницу." },
  { key: "07-26", name: "мч. Маркиана Иконийского", kind: "icon", desc: "Св. мученик Маркиан, юный проповедник из Иконии, обратил многих язычников ко Христу. За это был избит и отправлен к правителю Переннию в Каппадокию. Несмотря на уговоры и угрозы, смело исповедал веру, обличив язычество." },
  { key: "07-26", name: "Собор всех святых, в земле Литовской просиявших", kind: "feast", desc: "Празднование собора Литовских святых установлено по благословению Священного Синода Русской Православной Церкви 30 августа 2019 года. Днем памяти святых Литвы определено 26 июля, когда празднуется местная память виленских мучеников Антония, Иоанна и Евстафия." },
  { key: "07-27", name: "Ап. от 70-ти Акилы", kind: "saint", desc: "Ап. Акила, иудей из Понта, жил вместе со своей женой Прискиллой в Италии, а затем переселился в Коринф. Там они приняли крещение от апостола Павла и стали его верными учениками." },
  { key: "07-27", name: "Прп. Стефана Махрищского", kind: "saint", desc: "Прп. Стефан Махрищский, уроженец Киева, принял монашество в Киево-Печерском монастыре. Спасаясь от католических гонений, святой удалился в местечко Махрище (в 35 верстах от Троице-Сергиевой Лавры) и основал обитель в честь Св." },
  { key: "07-27", name: "мч. Иуста Римского", kind: "saint", desc: "Св. мученик Иуст, римский воин-язычник, обратился ко Христу после явления ему Животворящего Креста. Раздав имущество нищим, он предстал перед судом сановника Магнезия как христианин." },
  { key: "07-27", name: "прп. Еллия монаха", kind: "saint", desc: "Прп. Еллий, египетский подвижник IV века, с детства воспитывался в монастыре, а затем удалился в пустыню, где достиг высокого совершенства. Обладая великой верой, даром прозорливости и смирением, он повелевал дикими животными: использовал осла для переноса ноши и переплывал реку на крокодиле." },
  { key: "07-27", name: "прп. Онисима Магнезийского, чудотворца", kind: "saint", desc: "Прп. Онисим, чудотворец IV века, основал монастырь в Магнезии (Малая Азия). Пострадал за Христа при Диоклетиане. Преподобный Онисим чудотворец жил в IV веке, основал монастырь в Магнезии." },
  { key: "07-27", name: "мч. Иоанна Мервского", kind: "saint", desc: "Мч. Иоанн Мервский пострадал в IV веке во время персидского нашествия на Центральную Азию. Его имя, не сохранившееся в церковных источниках, было обнаружено в мусульманских исторических хрониках." },
  { key: "07-27", name: "прп. Никодима Святогорца", kind: "saint", desc: "Прп. Никодим Святогорец (1748-1809) – выдающийся афонский подвижник и богослов. Приняв монашество в 26 лет, он посвятил жизнь литературным трудам: редактировал \"Добротолюбие\", писал аскетические сочинения и толкования Священного Писания, составлял богослужебные книги." },
  { key: "07-27", name: "Сщмч. Константина Богоявленского, пресвитера", kind: "saint", desc: "Сщмч. Константин Богоявленский (1896-1918) родился в семье екатеринбургского диакона, окончил Пермскую духовную семинарию и был рукоположен в священники села Меркушино – места явления нетленных мощей св." },
  { key: "07-27", name: "сщмч. Николая Порецкого, пресвитера", kind: "saint", desc: "Сщмч. Николай Порецкий (1865-1933) родился в семье псаломщика Тверской губернии. Окончив семинарию, служил священником в храме Влахернской иконы Божией Матери под Москвой." },
  { key: "07-28", name: "равноап. вел. кн. Владимира, во Святом Крещении Василия", kind: "saint", desc: "Великий князь Владимир Святославич (†1015), крестивший Русь в 988 году, начал своё правление в Киеве как убеждённый язычник. Однако казнь варягов-христиан Феодора и Иоанна заставила его сомневаться в истинности язычества.", lifeId: "olga-vladimir" },
  { key: "07-28", name: "Собор Киевских святых", kind: "feast", desc: "Несмотря на то, что Киевская кафедра является самой древней и была основана первой на территории древней Руси, праздник Собора Киевских святых является достаточно новым, так как был установлен лишь в 2011 году." },
  { key: "07-28", name: "Мч. Авудима Тенедосского", kind: "saint", desc: "Св. мученик Авудим Тенедосский (IV в.) принял смерть за веру в период гонений императора Диоклетиана. Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмите кнопку " },
  { key: "07-28", name: "Сщмч. Петра Троицкого, диакона", kind: "saint", desc: "Сщмч. Петр Троицкий родился в 1897 г. в семье псаломщика под Москвой. После службы в Красной армии и плена в Польше работал на телеграфе. Позже оставил гражданскую службу и устроился служить псаломщиком, а в 1930 г." },
  { key: "07-29", name: "Сщмч. Афиногена, епископа Пидахфойского, и десяти учеников его", kind: "saint", desc: "Сщмч. Афиноген и его 10 учеников приняли смерть за Христа во время гонений в Севастии. Когда правитель Филомарх устроил языческий праздник, христиане отказались поклоняться идолам." },
  { key: "07-29", name: "мч. Антиоха врача, Севастийского", kind: "saint", desc: "Св. мученик Антиох, врач из Севастии Каппадокийской, пострадал в IV веке. Когда язычники узнали о его вере, он был подвергнут жестоким пыткам: брошен в кипящую воду, отдан на растерзание зверям – но оставался невредим." },
  { key: "07-29", name: "мц. Иулии девы", kind: "saint", desc: "Св. мученица Иулия, карфагенская христианка, в детстве попала в рабство к сирийскому купцу. Сохраняя веру, она отказалась отречься от Христа. Во время морского путешествия на Корсике разъярённые язычники распяли её на кресте." },
  { key: "07-29", name: "Память святых отцов IV Вселенского Собора", year: "451", kind: "feast", desc: "Четвертый Вселенский Собор, на котором присутствовали 630 епископов, состоялся в 451 году в городе Халкидоне при императоре Маркиане (450–457). Еще при жизни императора Феодосия II (408–450) в 448 году Евсевий, епископ Дорилейский, донес Со" },
  { key: "07-29", name: "Блж. Матроны Анемнясевской (Беляковой), исп.", kind: "saint", desc: "Блж. Матрона Анемнясевская (1864-1936) родилась в бедной крестьянской семье в Рязанской губернии. В 7 лет после болезни оспой ослепла, а в 10 лет после побоев матери полностью лишилась возможности ходить, оставшись прикованной к постели.", lifeId: "matrona" },
  { key: "07-29", name: "прмч. Ардалиона (Пономарева), архимандрита", kind: "saint", desc: "Прмч. Ардалион (в миру Александр Пономарев) родился в семье священника, окончил Пермскую семинарию и более 30 лет служил на Урале, занимаясь миссионерством и духовным просвещением." },
  { key: "07-29", name: "Чирская Псковская", year: "1420", kind: "saint", desc: "Чирская (Псковская) икона Божией Матери – один из древнейших списков иконы Божией Матери Одигитрии. Первоначально икона находилась в храме в честь Рождества Христова села Чирски Псковской епархии, отчего и получила название Чирской." },
  { key: "07-30", name: "Вмц. Марины (Маргариты) Антиохийской", kind: "saint", desc: "Вмц. Марина (Маргарита) Антиохийская (IV в.) родилась в Малой Азии (ныне Турции) в семье языческого жреца. В 12 лет она тайно приняла крещение. В 15 лет, когда правитель Олимврий предложил ей брак, Марина смело исповедала себя христианкой." },
  { key: "07-30", name: "Прп. Иринарха Соловецкого, игумена", kind: "saint", desc: "Прп. Иринарх, игумен Соловецкий, принял постриг в Соловецком монастыре, где ревностно подражал подвижнической жизни основателей обители ‒ прпп. Зосимы и Савватия." },
  { key: "07-30", name: "прп. Леонида Устьнедумского, иеромонаха", kind: "saint", desc: "Прп. Леонид Устьнедумский (1551–1654) родился в крестьянской семье под Новгородом. В 50 лет от роду по видению отправился за иконой Богородицы Одигитрии в Моржевскую пустынь, затем основал обитель на реке Лузе." },
  { key: "07-30", name: "прп. Лазаря Галисийского, иеромонаха", kind: "saint", desc: "Прп. Лазарь Галисийский (†1053) родился в Малой Азии, принял монашество в Палестинской лавре св. Саввы. После 10 лет подвижничества вернулся на родину и поселился на горе Галисийской близ Эфеса, где удостоился видения огненного столпа с ангельским пением." },
  { key: "07-30", name: "Святогорская", year: "1569", kind: "saint", desc: "30 июля в Святогорскую Свято-Успенскую лавру приезжают тысячи паломников, чтобы помолиться у величайшей святыни Донбасса – Святогорской иконы Божией Матери." },
  { key: "07-31", name: "Мч. Емилиана Доростольского", kind: "saint", desc: "Св. мученик Емилиан († 363) был рабом-христианином в языческом городе. Возмутившись гонениями на христиан, он тайно разрушил языческое капище. Когда за это хотели казнить невинного, святой добровольно признался." },
  { key: "07-31", name: "мч. Иакинфа Амастридского", kind: "saint", desc: "Св. мученик Иакинф (IV век) родился в Амастриде в христианской семье. С детства проявил чудесную веру – в 3 года по его молитве воскрес умерший ребенок." },
  { key: "07-31", name: "Прп. Иоанна Многострадального, Печерского, в Ближних пещерах", kind: "saint", desc: "Прп. Иоанн Многострадальный, подвизавшийся в Киево-Печерской Лавре, прославился тридцатилетним подвигом борьбы с плотской страстью. Приняв затворничество, он изнурял тело постом, веригами и бдениями." },
  { key: "07-31", name: "прп. Памвы, затворника Печерского, в Дальних пещерах, иеромонаха", kind: "saint", desc: "Прп. Памва Печерский (XIII в.) ‒ иеромонах Киево-Печерской Лавры, пострадавший во время татарского нашествия. Посланный за провизией при осаде монастыря, был схвачен и мучим за отказ отречься от Христа." },
  { key: "07-31", name: "прп. Памвы пустынника, Нитрийского", kind: "saint", desc: "Прп. Памва Нитрийский (IV в.) ‒ великий египетский подвижник. Прославился тремя главными добродетелями: постоянным постом, молчанием и рукоделием. Всю жизнь руководствовался словами псалма: \"сохраню пути моя, еже не согрешати ми языком моим\", всегда отвечал лишь после долгого размышления." },
  { key: "07-31", name: "Собор Калужских святых", kind: "feast", desc: "Поименный список Собора Калужских святых утвержден решением Священного Синода 25 июля 2024 года (журнал № 87). Прикрепить к своему календарю Вебмастеру Обратная связь Ошибка? Выделение + кнопка! Если заметили ошибку, выделите текст и нажмит" },
];
